<?php
declare(strict_types=1);
require_once __DIR__.'/../modelo/v2/journey/JourneyV11OperationalContext.php';
date_default_timezone_set('UTC');
$ref=new ReflectionClass(JourneyPairingService::class);
$pairing=$ref->newInstanceWithoutConstructor(); $ref->getProperty('defaultToleranceSeconds')->setValue($pairing,14400);
$policy=['policy_id'=>9,'version'=>6,'early_entry_minutes'=>10,'repeat_minutes'=>5,'exit_priority_minutes'=>60];
$segment=static fn($s,$e,$o=1)=>['ordinal'=>$o,'scheduled_start_utc'=>$s,'scheduled_end_utc'=>$e,'tipo_segmento'=>'WORK'];
$punch=static fn($id,$time,$status='RECEIVED')=>['id'=>$id,'id_personal_resuelto'=>1005,'id_estacion_resuelta'=>1,'ocurrido_at_utc'=>$time,'processing_status'=>$status,'validation_flags'=>'[]'];
$date='2026-11-27'; $key="1005:1:$date";
$day=[$segment("$date 13:00:00","$date 21:00:00")];
$events=[$punch(1,"$date 12:55:00"),$punch(2,"$date 21:00:00"),$punch(3,"$date 21:02:00")];
$preview=static function(array $segments,array $p,?array $pol,bool $closed=false) use ($pairing): array {
    $r=$pairing->previewCandidatePositions($segments,$p,$pol,$closed,1,1005);
    $r['raw_punches']=$p; $r['window_started']=true;
    $r['level2_evidence']=$closed?['id_estacion'=>1,'window_from_utc'=>'2026-11-27 09:00:00','window_to_utc'=>'2026-11-28 01:00:00','window_level2_status'=>'VERIFIED','evaluation_ref'=>'ref1']:null;
    return $r;
};
$diagnostic=static function(array $seg,array $events,array $pol,bool $closed=false,bool $materialized=false) use ($preview,$key,$date): array {
    $p=[$key=>$preview($seg,$events,$pol,$closed)];$c=[];
    foreach($seg as $s)$c[$key.':'.$s['ordinal']]=['worker'=>1005,'station'=>1,'physical_station'=>1,'date'=>$date,'segment'=>$s,'policy'=>$pol,'materialized'=>$materialized];
    return ['candidate_segments'=>$c,'journey_previews'=>$p,'position_summary'=>JourneyV11OperationalContext::summarizePositionPreviews($p)];
};
$build=static fn($d,$claims=[],$latest=null,$p2=null,$p2ForLatest=null)=>JourneyV11EvaluationPlan::build($d,1005,1,$date,$claims,$latest,$p2,$p2ForLatest);
$n=0;$check=static function($ok,$name)use(&$n){if(!$ok)throw new RuntimeException('FAIL '.$name);echo 'PASS '.$name.PHP_EOL;++$n;};
$d=$diagnostic($day,$events,$policy);$plan=$build($d);$slot=$plan['pairing_results']['segment_results'][0];
$check($slot['entry_punch_id']===1&&$slot['exit_punch_id']===3&&count($slot['associated_punches'])===3,'normalize existing classifier to existing writer');
$check($plan['pairing_results']['overall_status']==='PENDING_SYNC_COMPLETION'&&!$plan['closed'],'unknown Level2 is not final');
$check($plan['eligible_for_writer']&&$plan['reason']==='P1_MISSING','noncompeting candidate produces plan');
$check($plan['fingerprint']===$build($d)['fingerprint'],'identical inputs stable');
$check($plan['fingerprint']===$build($diagnostic($day,$events,$policy,false,true))['fingerprint'],'materialization alone does not change hash');
$d2=$diagnostic($day,[...$events,$punch(4,"$date 20:30:00")],$policy);$check($plan['fingerprint']!==$build($d2)['fingerprint'],'late event changes hash');
$d2=$diagnostic($day,$events,array_replace($policy,['repeat_minutes'=>4]));$check($plan['fingerprint']!==$build($d2)['fingerprint'],'effective parameters change hash');
$d2=$diagnostic($day,$events,$policy,true);$p2=$build($d2);$check($p2['closed']&&$p2['pairing_results']['overall_status']==='EXACT_PAIR'&&$p2['fingerprint']!==$plan['fingerprint'],'coverage and closure change result and hash');
$d2['journey_previews'][$key]['level2_evidence']['evaluation_ref']='random_ref2';$check($p2['fingerprint']===$build($d2)['fingerprint'],'random reference alone does not force new revision');
$latest=['id'=>12,'revision_numero'=>2,'version_algoritmo'=>'v2.5-p1-v11','fingerprint_ejecucion'=>$plan['fingerprint']];
$check($build($d,[],$latest)['reason']==='P2_MISSING_OR_STALE','P1 recovery when P2 missing');
$check($build($d,[],$latest,['id_pareo_jornada'=>11])['reason']==='P2_MISSING_OR_STALE','P2 points to older P1');
$check($build($d,[],$latest,['id_pareo_jornada'=>12])['reason']==='UP_TO_DATE','latest P1 and P2 unchanged');
$check(in_array('J1_P2_HISTORICAL_REUSE_UNVERIFIED',$build($d,[],$latest,['id_pareo_jornada'=>11],['id'=>10,'id_pareo_jornada'=>12])['blockers'],true),'historical P2 reuse cannot displace latest result silently');
$check($build($d,[],array_replace($latest,['fingerprint_ejecucion'=>str_repeat('a',64)]))['reason']==='P1_INPUTS_CHANGED','older fingerprint cannot resurrect superseded result');
$claim=['pairing_id'=>99,'id_estacion'=>1,'fecha_jornada_local'=>'2026-11-26','version_algoritmo'=>'v2.4-p1','punch_id'=>1,'claim_role'=>'EXIT'];
$blocked=$build($d,[$claim]);$check(!$blocked['eligible_for_writer']&&in_array('J1_ACTIVE_REVISION_COMPETITION',$blocked['blockers'],true),'active competing revision blocks');
$own=array_replace($claim,['fecha_jornada_local'=>$date]);$check($build($d,[$own])['fingerprint']===$plan['fingerprint'],'own active claim does not change hash');
$d2=$d;$d2['journey_previews']['1005:1:2026-11-26']=$preview([$segment('2026-11-26 23:00:00','2026-11-27 13:00:00')],$events,$policy);$d2['position_summary']=JourneyV11OperationalContext::summarizePositionPreviews($d2['journey_previews']);
$check(in_array('J1_POSSIBLE_CROSS_JOURNEY_COMPETITION',$build($d2)['blockers'],true),'possible competitor blocks without claiming deterministic ownership');
$split=[$segment("$date 13:00:00","$date 17:00:00",1),$segment("$date 17:10:00","$date 21:00:00",2)];
$e=[$punch(5,"$date 17:05:00")];$check(in_array('J1_CROSS_SEGMENT_ALTERNATIVES',$build($diagnostic($split,$e,$policy))['blockers'],true),'shared segment boundary detected');
$bad=$punch(9,"$date 13:00:00",'REJECTED');$p=$build($diagnostic($day,[$bad],$policy));$check(!$p['eligible_for_writer']&&$p['pairing_results']['unassigned_punches'][0]===['punch_id'=>9,'role'=>'AMBIGUOUS'],'unverified event retained and blocked');
$d2=$d;$d2['journey_previews'][$key]['window_started']=false;$check(in_array('J1_WINDOW_NOT_OPEN',$build($d2)['blockers'],true),'future window not writable');
putenv('CHECADOR_J1_V11_PERSISTENCE_ENABLED');$check(!JourneyPairingService::v11PersistenceEnabled(),'persistence disabled by default');
echo "$n PASS (in-memory plan and existing classifiers; no MariaDB writes)\n";
